WITH src AS (SELECT $p1$[{"draft_id": "draft_7bfc366b37ef4b46", "lead_id": "L12", "source": "csv", "lead_temperature": "Hot", "service_fit_primary": "LinkedIn Outreach & Automation", "service_fit_secondary": "ICP Mapping & Lead Scoring", "subject": "Personalized LinkedIn Outreach for Saffron Trails", "recipient": "pooja.founder@gmail.example", "body": "Hi Pooja, I came across Saffron Trails and noticed you're an HR head planning team offsites in the corporate travel industry. I'd love to help you save time with done-for-you offsite packages. I've generated 5 personalized direct message angles tailored to your needs. Learn more about how Myntmore can support you at myntmore.com/founder-meeting.", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary LinkedIn Outreach & Automation from submitted signals (\\bdm angles?\\b; tool_prior:dm_angle_generator). Secondary: ICP Mapping & Lead Scoring.", "created_at": "2026-10-14T20:27:33.388Z", "validation_ok": true, "validation_errors": [], "draft_source": "nvidia"}, {"draft_id": "draft_9112a2f67d20dd0b", "lead_id": "L13", "source": "csv", "lead_temperature": "Hot", "service_fit_primary": "ICP Mapping & Lead Scoring", "service_fit_secondary": null, "subject": "Next Steps for ICP Mapping at PaySure", "recipient": "sid@paysure.example", "body": "Hi Siddharth, thanks for reaching out to Myntmore. We'd love to help you with ICP mapping for your payment reconciliation software targeting D2C brands with Rs 5 to 50 crore annual revenue. Our analysis suggests 3 potential ICPs and value propositions, along with potential channel partners like CA firms. Would you like to discuss further? Schedule a meeting with our founder at myntmore.com/founder-meeting.", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary ICP Mapping & Lead Scoring from submitted signals (\\bicp\\b; tool_prior:icp_builder).", "created_at": "2026-10-14T20:27:37.585Z", "validation_ok": true, "validation_errors": [], "draft_source": "nvidia"}, {"draft_id": "draft_803b129529366f26", "lead_id": "L15", "source": "csv", "lead_temperature": "Warm", "service_fit_primary": "Personal Branding", "service_fit_secondary": null, "subject": "Following up on your founder presence analyzer session", "recipient": "aditi@stackwisehr.example", "body": "Hi Aditi,\n\nThanks for trying Myntmore's founder presence analyzer for Stackwise HR.\nYou shared: Checking our CEO's presence. Posts 3 to 5 times a month, engagement 20 to 50\nThe tool returned: Presence score 38/100. Biggest gaps: narrative and visibility\nIf helpful, we can talk about personal branding next steps.\nBook a founder meeting: https://myntmore.com/founder-meeting\n\nBest,\nMyntmore", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary Personal Branding from submitted signals (\\bfounder presence\\b; tool_prior:founder_presence_analyzer).", "created_at": "2026-10-14T20:27:40.965Z", "validation_ok": true, "validation_errors": [], "draft_source": "template_fallback"}, {"draft_id": "draft_3c5130f9720d7a0b", "lead_id": "L16", "source": "csv", "lead_temperature": "Hot", "service_fit_primary": "Personal Branding", "service_fit_secondary": "ICP Mapping & Lead Scoring", "subject": "Boost Your LinkedIn Profile with Personal Branding", "recipient": "tanvi@ghostpenstudio.example", "body": "Hi Tanvi, I came across your profile and noticed that your current headline could be improved. Our tool suggests that your headline clarity score is 70/100. We've also generated three new headline options that might better fit your role as a Ghostwriter for founders. Would you like to discuss how personal branding can elevate your LinkedIn presence? Learn more about how we can help at myntmore.com/founder-meeting.", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary Personal Branding from submitted signals (\\bghostwrit; \\bprofile optimi[sz]er\\b; tool_prior:profile_optimizer). Secondary: ICP Mapping & Lead Scoring.", "created_at": "2026-10-14T20:27:44.372Z", "validation_ok": true, "validation_errors": [], "draft_source": "nvidia"}, {"draft_id": "draft_2a85079255a8d088", "lead_id": "L17", "source": "csv", "lead_temperature": "Hot", "service_fit_primary": "AI Lead Generation", "service_fit_secondary": "ICP Mapping & Lead Scoring", "subject": "Quick note on your lead magnet ideas results", "recipient": "imran.sheikh@nimbusit.example", "body": "Hi Imran,\n\nThanks for trying Myntmore's lead magnet ideas for Nimbus IT Services.\nYou shared: Business: IT staffing and managed services for US mid-market companies. ICP: CTOs. Tone: …\nThe tool returned: 3 ideas: a cloud cost calculator, a CTO hiring benchmark, an IT audit checklist\nIf helpful, we can talk about AI lead generation next steps.\nBook a founder meeting: https://myntmore.com/founder-meeting\n\nBest,\nMyntmore", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary AI Lead Generation from submitted signals (\\blead magnet\\b; tool_prior:lead_magnet_ideas). Secondary: ICP Mapping & Lead Scoring.", "created_at": "2026-10-14T20:27:46.421Z", "validation_ok": true, "validation_errors": [], "draft_source": "template_fallback"}, {"draft_id": "draft_06e7d6068f753370", "lead_id": "L20", "source": "csv", "lead_temperature": "Hot", "service_fit_primary": "LinkedIn Outreach & Automation", "service_fit_secondary": null, "subject": "DuneLogix LinkedIn Outreach Projection", "recipient": "fatima@dunelogix.example", "body": "Hi Fatima, thanks for using our ROI calculator. We've exported the PDF with your LinkedIn outreach projection. Based on your input, we project 1 deal worth AED 40,000 with an ROI of 48% on a total cost of AED 27,000. We'd love to discuss how Myntmore can help you achieve this goal. Schedule a call with our founder at [myntmore.com/founder-meeting](myntmore.com/founder-meeting).", "cta_url": "https://myntmore.com/founder-meeting", "status": "draft_only", "send_attempted": false, "qualification_reason": "Primary LinkedIn Outreach & Automation from submitted signals (\\bconnection requests?\\b; tool_prior:roi_calculator).", "created_at": "2026-10-14T20:27:49.865Z", "validation_ok": true, "validation_errors": [], "draft_source": "nvidia"}]$p1::jsonb AS arr)
INSERT INTO email_draft_artifacts (draft_id, lead_id, idempotency_key, artifact, status, send_attempted, created_at, updated_at)
SELECT elem->>'draft_id', elem->>'lead_id', (elem->>'lead_id')||'|'||(elem->>'lead_temperature'), elem, 'draft_only', false, now(), now()
FROM jsonb_array_elements((SELECT arr FROM src)) AS elem
ON CONFLICT (draft_id) DO UPDATE SET artifact=EXCLUDED.artifact, status=EXCLUDED.status, send_attempted=false, updated_at=now();